# Fix CardEnc usage
from pysat.solvers import Solver
from pysat.card import CardEnc, EncType
import itertools

n = 14
edge_var = {}
var_count = 0
for u in range(n):
    for v in range(u+1, n):
        var_count += 1
        edge_var[(u,v)] = var_count

color_var = {}
for v in range(n):
    for k in range(3):
        var_count += 1
        color_var[(v,k)] = var_count

print("Total variables:", var_count)

clauses = []

for v in range(n):
    clauses.append([color_var[(v,k)] for k in range(3)])

for u in range(n):
    for v in range(u+1, n):
        e = edge_var[(u,v)]
        for k in range(3):
            clauses.append([-e, -color_var[(u,k)], -color_var[(v,k)]])

def add_cycle_constraints(length):
    count = 0
    for vertices in itertools.combinations(range(n), length):
        first = vertices[0]
        rest = vertices[1:]
        for perm in itertools.permutations(rest):
            seq = (first,) + perm
            if seq[1] < seq[-1]:
                c = []
                ok = True
                for i in range(length):
                    a = seq[i]
                    b = seq[(i+1)%length]
                    if a > b:
                        a,b = b,a
                    if (a,b) not in edge_var:
                        ok = False
                        break
                    c.append(-edge_var[(a,b)])
                if ok:
                    clauses.append(c)
                    count += 1
    return count

for L in [3,4,5,6]:
    c = add_cycle_constraints(L)
    print(f"Cycle length {L} constraints: {c}")

print("Total clauses before cardinality:", len(clauses))

atleast = 19
card = CardEnc.atleast(lits=list(edge_var.values()), bound=atleast, encoding=EncType.totalizer, top_id=var_count)
print("Card type:", type(card))
print("Card clauses:", len(card.clauses))
print("Card nvars:", card.nv)
clauses.extend(card.clauses)
var_count = card.nv
print("Total clauses:", len(clauses))
print("Total variables after card:", var_count)

solver = Solver(name='glucose4')
for clause in clauses:
    solver.add_clause(clause)

sat = solver.solve()
print("SAT:", sat)

if sat:
    model = solver.get_model()
    edges = []
    for (u,v), var in edge_var.items():
        if var in model:
            edges.append((u,v))
    print("Number of edges:", len(edges))
    print("Edges:", edges)
    colors = {}
    for v in range(n):
        for k in range(3):
            if color_var[(v,k)] in model:
                colors[v] = k
                break
    print("Colors:", colors)
    # verify girth
    import collections
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)
    girth = float('inf')
    for start in range(n):
        dist = [-1]*n
        parent = [-1]*n
        q = collections.deque([start])
        dist[start] = 0
        while q:
            u = q.popleft()
            for w in adj[u]:
                if dist[w] == -1:
                    dist[w] = dist[u] + 1
                    parent[w] = u
                    q.append(w)
                elif parent[u] != w and parent[w] != u:
                    cycle_len = dist[u] + dist[w] + 1
                    girth = min(girth, cycle_len)
    print("Girth:", girth)
    valid_color = True
    for u,v in edges:
        if colors[u] == colors[v]:
            valid_color = False
            break
    print("Valid coloring:", valid_color)
else:
    print("UNSAT")

solver.delete()

# Let's try a smarter backtracking approach
# Build graph incrementally, maintaining girth >= 7 and 3-colorability

import itertools

n = 14

class GraphBuilder:
    def __init__(self, n):
        self.n = n
        self.edges = []
        self.adj = [[] for _ in range(n)]
        self.colors = [-1] * n

    def add_edge(self, u, v):
        self.edges.append((u, v))
        self.adj[u].append(v)
        self.adj[v].append(u)

    def remove_last_edge(self):
        u, v = self.edges.pop()
        self.adj[u].remove(v)
        self.adj[v].remove(u)

    def shortest_cycle_through_edge(self, u, v):
        """Find shortest cycle containing edge (u,v), or inf if none"""
        # Remove edge temporarily and find shortest path from u to v
        self.adj[u].remove(v)
        self.adj[v].remove(u)

        dist = [-1] * self.n
        parent = [-1] * self.n
        from collections import deque
        q = deque([u])
        dist[u] = 0

        while q:
            x = q.popleft()
            if x == v:
                break
            for y in self.adj[x]:
                if dist[y] == -1:
                    dist[y] = dist[x] + 1
                    parent[y] = x
                    q.append(y)

        # Restore edge
        self.adj[u].append(v)
        self.adj[v].append(u)

        if dist[v] == -1:
            return float('inf')
        return dist[v] + 1

    def girth(self):
        """Compute girth of current graph"""
        best = float('inf')
        for u, v in self.edges:
            c = self.shortest_cycle_through_edge(u, v)
            best = min(best, c)
        return best

    def is_3_colorable(self):
        """Check if current graph is 3-colorable using backtracking"""
        colors = [-1] * self.n

        def can_color(v):
            if v == self.n:
                return True
            if colors[v] != -1:
                return can_color(v + 1)

            for c in range(3):
                ok = True
                for u in self.adj[v]:
                    if colors[u] == c:
                        ok = False
                        break
                if ok:
                    colors[v] = c
                    if can_color(v + 1):
                        return True
                    colors[v] = -1
            return False

        return can_color(0)

    def is_3_colorable_fast(self):
        """Faster check using greedy + backtracking on uncolored vertices"""
        colors = [-1] * self.n

        # Order vertices by degree (descending)
        order = sorted(range(self.n), key=lambda x: len(self.adj[x]), reverse=True)

        def can_color(idx):
            if idx == self.n:
                return True
            v = order[idx]
            if colors[v] != -1:
                return can_color(idx + 1)

            for c in range(3):
                ok = True
                for u in self.adj[v]:
                    if colors[u] == c:
                        ok = False
                        break
                if ok:
                    colors[v] = c
                    if can_color(idx + 1):
                        return True
                    colors[v] = -1
            return False

        return can_color(0)

# Try to build a graph with >= 19 edges
# Strategy: start with a long cycle, then add edges

builder = GraphBuilder(n)

# Start with a 14-cycle
for i in range(n):
    builder.add_edge(i, (i+1) % n)

print("Initial edges:", len(builder.edges))
print("Girth:", builder.girth())
print("3-colorable:", builder.is_3_colorable_fast())

# Try adding chords
# All possible chords
all_pairs = [(u, v) for u in range(n) for v in range(u+1, n) if (u, v) not in [(i, (i+1)%n) for i in range(n)] and (v, u) not in [(i, (i+1)%n) for i in range(n)]]
print("Possible chords:", len(all_pairs))

# Try greedy: add edges that don't violate girth or colorability
added = 0
for u, v in all_pairs:
    builder.add_edge(u, v)
    g = builder.girth()
    if g >= 7 and builder.is_3_colorable_fast():
        added += 1
        print(f"Added ({u},{v}), girth={g}, total edges={len(builder.edges)}")
        if len(builder.edges) >= 19:
            break
    else:
        builder.remove_last_edge()

print(f"\nFinal edges: {len(builder.edges)}")
print(f"Girth: {builder.girth()}")
print(f"3-colorable: {builder.is_3_colorable_fast()}")
print(f"Edges: {builder.edges}")
